// typed_a1_check_rt.h: round A1's differential check (a1_typed_check.cpp, generated by tools/typed_lift.py --check-tu;
// docs/decomp_a1.md section 4). Only the check translation unit and the offline harness (tools/a1_harness.cpp)
// include it.
//
// Each check runs two legs on logged memory: the reference (a copy of the function's lifted text, lift_d1's output,
// on a copy of the caller's context) and the typed function (on the values the call passes). Neither leg changes
// memory: a store is appended to the leg's log, a load reads main RAM (or the runtime's slow path) overlaid with the
// leg's own earlier stores. Then: the return value (v0 / f0, by the function's return kind) against the reference's
// context, the stores (address, size, value, in order) against each other, ra / sp, every context slot the reference
// changed that is neither returned nor in the function's scratch set (must be none). The call itself then runs as
// usual. The counts go to the [a1] line (SOTC_A1_LOG=<frames>) and, offline, to the harness's report.
#pragma once

#include "typed_a1_rt.h"

#include <cstdio>
#include <cstdlib>
#include <new>

#ifndef LIFT_D1_HELPERS
#define LIFT_D1_HELPERS
namespace lift_d1
{
    inline uint64_t sx64(uint32_t v) { return static_cast<uint64_t>(static_cast<int64_t>(static_cast<int32_t>(v))); }
    inline uint32_t bits(float f)
    {
        uint32_t b;
        std::memcpy(&b, &f, 4);
        return b;
    }
    inline float flt(uint32_t b)
    {
        float f;
        std::memcpy(&f, &b, 4);
        return f;
    }
}
#define LIFT_SET_FACC(x) (facc = (x))
#endif

namespace a1ck
{
    struct CkEntry
    {
        const char *name;
        uint32_t addr;
        void (*run)(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime); // a check with the inputs from ctx
    };
    extern const CkEntry kEntries[];
    extern const uint32_t kEntryCount;

    struct CkStore
    {
        uint32_t a, n;
        uint64_t v;
    };
    constexpr int kMaxStores = 512;
    constexpr uint32_t kMaxFunctions = 4096;
    struct CkState
    {
        R5900Context ctx; // the reference's context (first: the block is 16-aligned)
        CkStore log[2][kMaxStores];
        int n[2];
        int cur;
        bool ovf, io, active;
        uint8_t *ram;
        PS2Runtime *rt;
    };
    struct CkStats
    {
        uint64_t calls = 0, differ = 0, ret = 0, mem = 0, pc = 0, sp = 0, other = 0, io = 0, ovf = 0, nested = 0;
        uint64_t droppedChanged = 0; // calls where the reference changed a scratch slot the typed function drops
        uint32_t perCalls[kMaxFunctions] = {}, perDiffer[kMaxFunctions] = {};
        int firstId = -1;
        char first[256] = {};
    };
    inline CkStats g_stats;
    // the slow path for an address outside main RAM (in-run: the runtime's; offline: the harness's)
    inline uint64_t (*g_slowRead)(uint8_t *ram, PS2Runtime *rt, uint32_t a, uint32_t n) = nullptr;

    inline CkState &ckState()
    {
        thread_local CkState *s = nullptr;
        if (!s)
        {
            void *m = std::malloc(sizeof(CkState) + 16);
            void *p = reinterpret_cast<void *>((reinterpret_cast<uintptr_t>(m) + 15u) & ~uintptr_t(15));
            s = new (p) CkState();
        }
        return *s;
    }

    template <typename T>
    inline T ckRd(uint32_t a)
    {
        CkState &s = ckState();
        uint8_t b[sizeof(T)];
        if (a < PS2_RAM_SIZE && a + sizeof(T) <= PS2_RAM_SIZE)
            std::memcpy(b, s.ram + a, sizeof(T));
        else
        {
            s.io = true;
            const uint64_t v = g_slowRead ? g_slowRead(s.ram, s.rt, a, sizeof(T)) : 0u;
            std::memcpy(b, &v, sizeof(T));
        }
        const int c = s.cur;
        for (int i = 0; i < s.n[c] && i < kMaxStores; ++i)
        {
            const CkStore &w = s.log[c][i];
            for (uint32_t k = 0; k < sizeof(T); ++k)
            {
                const uint32_t x = a + k;
                if (x - w.a < w.n)
                    b[k] = static_cast<uint8_t>(w.v >> (8u * (x - w.a)));
            }
        }
        T v;
        std::memcpy(&v, b, sizeof(T));
        return v;
    }
    template <typename T>
    inline void ckWr(uint32_t a, T v)
    {
        CkState &s = ckState();
        const int c = s.cur;
        if (s.n[c] >= kMaxStores)
        {
            s.ovf = true;
            return;
        }
        uint64_t x = 0;
        std::memcpy(&x, &v, sizeof(T));
        s.log[c][s.n[c]++] = {a, static_cast<uint32_t>(sizeof(T)), x};
    }

    inline bool ckBegin(int id, uint8_t *ram, PS2Runtime *rt)
    {
        CkState &s = ckState();
        if (s.active)
        {
            ++g_stats.nested;
            return false;
        }
        s.active = true;
        s.n[0] = s.n[1] = 0;
        s.cur = 0;
        s.ovf = s.io = false;
        s.ram = ram;
        s.rt = rt;
        ++g_stats.calls;
        if (id >= 0 && static_cast<uint32_t>(id) < kMaxFunctions)
            ++g_stats.perCalls[id];
        return true;
    }
    inline R5900Context &ckCtx(const R5900Context *ctx)
    {
        CkState &s = ckState();
        std::memcpy(static_cast<void *>(&s.ctx), ctx, sizeof(R5900Context));
        return s.ctx;
    }
    inline void ckMid() { ckState().cur = 1; }

    inline uint32_t ckBits(float f)
    {
        uint32_t b;
        std::memcpy(&b, &f, 4);
        return b;
    }
    // kind: 0 void, 1 uint32_t (v0 sign-extended), 2 uint64_t, 3 float, 4 both; dg / df: the scratch GPRs / FPRs
    inline void ckEnd(int id, const R5900Context *in, const R5900Context &ref, int kind, uint64_t v0, float f0, uint32_t dg, uint32_t df)
    {
        CkState &s = ckState();
        bool ret = false, mem = false, pc = false, sp = false, other = false, dropped = false;
        if ((kind == 1 || kind == 2 || kind == 4) && Ps2GprU64(&ref, 2) != v0)
            ret = true;
        if ((kind == 3 || kind == 4) && ckBits(ref.f[0]) != ckBits(f0))
            ret = true;
        if (s.n[0] != s.n[1] || s.ovf)
            mem = true;
        else
            for (int i = 0; i < s.n[0]; ++i)
            {
                const CkStore &x = s.log[0][i], &y = s.log[1][i];
                if (x.a != y.a || x.n != y.n || x.v != y.v)
                    mem = true;
            }
        if (ref.pc != static_cast<uint32_t>(Ps2GprU64(in, 31)))
            pc = true;
        if (Ps2GprU64(&ref, 29) != Ps2GprU64(in, 29))
            sp = true;
        const uint32_t retg = (kind == 1 || kind == 2 || kind == 4) ? (1u << 2) : 0u;
        const uint32_t retf = (kind == 3 || kind == 4) ? 1u : 0u;
        for (int r = 1; r < 32; ++r)
        {
            if (std::memcmp(&ref.r[r], &in->r[r], 8) == 0)
                continue;
            if (dg & (1u << r))
                dropped = true;
            else if (!(retg & (1u << r)))
                other = true;
        }
        for (int r = 0; r < 32; ++r)
        {
            if (ckBits(ref.f[r]) == ckBits(in->f[r]))
                continue;
            if (df & (1u << r))
                dropped = true;
            else if (!(retf & (1u << r)))
                other = true;
        }
        if (ref.hi != in->hi || ref.lo != in->lo || ref.fcr31 != in->fcr31 || ckBits(ref.f_acc) != ckBits(in->f_acc))
            dropped = true; // hi / lo / fcr31 / the accumulator: always scratch (never an output of these leaves)
        if (s.io)
            ++g_stats.io;
        if (s.ovf)
            ++g_stats.ovf;
        if (dropped)
            ++g_stats.droppedChanged;
        if (ret || mem || pc || sp || other)
        {
            ++g_stats.differ;
            g_stats.ret += ret;
            g_stats.mem += mem;
            g_stats.pc += pc;
            g_stats.sp += sp;
            g_stats.other += other;
            if (id >= 0 && static_cast<uint32_t>(id) < kMaxFunctions)
                ++g_stats.perDiffer[id];
            if (g_stats.firstId < 0)
            {
                g_stats.firstId = id;
                std::snprintf(g_stats.first, sizeof(g_stats.first), "%s ret %d mem %d (stores %d / %d) pc %d sp %d other %d v0 %llx/%llx",
                              (id >= 0 && static_cast<uint32_t>(id) < kEntryCount) ? kEntries[id].name : "?", ret, mem, s.n[0], s.n[1], pc,
                              sp, other, (unsigned long long)Ps2GprU64(&ref, 2), (unsigned long long)v0);
            }
        }
        s.active = false;
    }

    inline void ckReport(unsigned long long frame)
    {
        const CkStats &g = g_stats;
        uint32_t fns = 0;
        for (uint32_t i = 0; i < kEntryCount && i < kMaxFunctions; ++i)
            fns += g.perCalls[i] ? 1u : 0u;
        std::fprintf(stderr, "[a1] frame %llu: checks %llu (functions reached %u of %u) differ %llu (ret %llu mem %llu pc %llu sp %llu other %llu); "
                             "slow-path loads %llu, log overflow %llu, nested %llu; scratch slots changed by the reference %llu%s%s\n",
                     frame, (unsigned long long)g.calls, fns, kEntryCount, (unsigned long long)g.differ, (unsigned long long)g.ret,
                     (unsigned long long)g.mem, (unsigned long long)g.pc, (unsigned long long)g.sp, (unsigned long long)g.other,
                     (unsigned long long)g.io, (unsigned long long)g.ovf, (unsigned long long)g.nested,
                     (unsigned long long)g.droppedChanged, g.firstId >= 0 ? "; first: " : "", g.first);
    }
}

