#define READ16_B(b, o) a1ck::ckRd<uint16_t>(A1CK_EA(b, o))
#define READ32_B(b, o) a1ck::ckRd<uint32_t>(A1CK_EA(b, o))
#define READ64_B(b, o) a1ck::ckRd<uint64_t>(A1CK_EA(b, o))
#define WRITE8_B(b, o, v) a1ck::ckWr<uint8_t>(A1CK_EA(b, o), (uint8_t)(v))
