#define WRITE64_B(b, o, v) a1ck::ckWr<uint64_t>(A1CK_EA(b, o), (uint64_t)(v))
#define READ8(a) a1ck::ckRd<uint8_t>((uint32_t)(a))
#define READ16(a) a1ck::ckRd<uint16_t>((uint32_t)(a))
#define READ32(a) a1ck::ckRd<uint32_t>((uint32_t)(a))
#define READ64(a) a1ck::ckRd<uint64_t>((uint32_t)(a))
#define WRITE8(a, v) a1ck::ckWr<uint8_t>((uint32_t)(a), (uint8_t)(v))
#define WRITE16(a, v) a1ck::ckWr<uint16_t>((uint32_t)(a), (uint16_t)(v))
#define WRITE32(a, v) a1ck::ckWr<uint32_t>((uint32_t)(a), (uint32_t)(v))
#define WRITE64(a, v) a1ck::ckWr<uint64_t>((uint32_t)(a), (uint64_t)(v))
